fn solve(input: Vec<char>) -> Vec<char> {
    // Requires clause to ensure the input has exactly 4 characters
    // and that they are all valid digit characters.
    // This is necessary to avoid panics when calling to_digit.
    requires!(input.len() == 4);
    requires!(input.iter().all(|&c| c.is_digit(10)));

    // Extract the digits from the input
    let d1 = input[0].to_digit(10).unwrap();
    let d2 = input[1].to_digit(10).unwrap();
    let d3 = input[2].to_digit(10).unwrap();
    let d4 = input[3].to_digit(10).unwrap();

    // Possible operators
    let operators = ['+', '-'];

    // Iterate through all combinations of operators
    // Invariant: At the start of each iteration, we have selected
    // op1, op2, and op3 from the operators.
    let mut found = false; // To track if we found a valid expression
    let mut output = Vec::new(); // To store the output if found

    // Loop through all combinations of operators
    for &op1 in &operators {
        for &op2 in &operators {
            for &op3 in &operators {
                // Calculate the result based on the current combination of operators
                let result = match op1 {
                    '+' => d1 + d2,
                    '-' => d1 - d2,
                    _ => unreachable!(),
                };
                let result = match op2 {
                    '+' => result + d3,
                    '-' => result - d3,
                    _ => unreachable!(),
                };
                let result = match op3 {
                    '+' => result + d4,
                    '-' => result - d4,
                    _ => unreachable!(),
                };

                // Check if the result equals 7
                if result == 7 {
                    // Construct the output
                    output.push(input[0]);
                    output.push(op1);
                    output.push(input[1]);
                    output.push(op2);
                    output.push(input[2]);
                    output.push(op3);
                    output.push(input[3]);
                    output.push('=');
                    output.push('7');
                    output.push('\n');
                    found = true; // Mark that we found a valid expression
                    break; // Exit the innermost loop
                }
            }
            if found {
                break; // Exit the middle loop
            }
        }
        if found {
            break; // Exit the outer loop
        }
    }

    // Ensures clause: If a valid expression is found, output is constructed correctly.
    // If no valid expression is found, output is an empty vector.
    ensures!(found ==> output.len() > 0);
    ensures!(!found ==> output.len() == 0);

    // If no valid expression is found, return an empty vector (this should not happen as per problem statement)
    output
}